frappe.ui.form.on('custom_work_allocation', {
    refresh: function(frm) {
        console.log('Form refreshed, work entries:', frm.doc.work_allocation);
        console.log('Available fields:', Object.keys(frm.fields_dict));

        // Set up the child table events - try different possible field names
        let child_table_field = null;
        if (frm.fields_dict.work_allocation) {
            child_table_field = 'work_allocation';
