            child_table_field = 'work';
        }

        if (child_table_field) {
            console.log('Using child table field:', child_table_field);
            frm.fields_dict[child_table_field].grid.wrapper.on('grid-row-render', function(e, grid_row) {
                setup_work_row_events(frm, grid_row);
            });
        } else {
            console.log('Child table field not found');
        }
    }
});

frappe.ui.form.on('Work', {
    // When start time changes, calculate end time
    expected_start_date: function(frm, cdt, cdn) {
        console.log('Start time changed:', frm, cdt, cdn);
        console.log('Row data:', locals[cdt][cdn]);
        calculate_end_time(frm, cdt, cdn);
        // Add a small delay to ensure end_time is calculated first
        setTimeout(() => {
            check_time_overlaps(frm, cdn);
        }, 100);
    },

    // When duration changes, recalculate end time
    expected_time_in_hours: function(frm, cdt, cdn) {
        console.log('Duration changed:', frm, cdt, cdn);
        console.log('Row data:', locals[cdt][cdn]);
        calculate_end_time(frm, cdt, cdn);
        // Add a small delay to ensure end_time is calculated first
        setTimeout(() => {
            check_time_overlaps(frm, cdn);
        }, 100);
    },

    // Also check when end_time is set (for manual entries)
    end_time: function(frm, cdt, cdn) {
        setTimeout(() => {
            check_time_overlaps(frm, cdn);
        }, 100);
    },

    // When a new row is added
    work_add: function(frm, cdt, cdn) {
        // Set default values if needed
        let row = locals[cdt][cdn];
        if (!row.expected_start_date) {
            // Set default start time to current time
            let now = new Date();
            let hours = now.getHours().toString().padStart(2, '0');
            let minutes = now.getMinutes().toString().padStart(2, '0');
            frappe.model.set_value(cdt, cdn, 'expected_start_date', `${hours}:${minutes}:00`);
        }
    }
});

// Function to calculate end time based on start time and duration
function calculate_end_time(frm, cdt, cdn) {
    let row = locals[cdt][cdn];
    console.log('Calculating end time for row:', row);

    if (row.expected_start_date && row.expected_time_in_hours) {
        let start_time = row.expected_start_date;
        let duration = parseFloat(row.expected_time_in_hours);

        console.log('Start time:', start_time, 'Duration:', duration);

        // Parse start time (handle HH:MM:SS format)
        let time_parts = start_time.split(':');
        let hours = parseInt(time_parts[0]);
        let minutes = parseInt(time_parts[1]);

        console.log('Parsed hours:', hours, 'minutes:', minutes);

        // Add duration
        let total_minutes = hours * 60 + minutes + (duration * 60);

        // Calculate end time
        let end_hours = Math.floor(total_minutes / 60) % 24;
        let end_minutes = Math.floor(total_minutes % 60);

        let end_time = `${end_hours.toString().padStart(2, '0')}:${end_minutes.toString().padStart(2, '0')}:00`;

        console.log('Calculated end time:', end_time);

        // Set end time without triggering events
        frappe.model.set_value(cdt, cdn, 'end_time', end_time);
    } else {
        console.log('Missing start time or duration');
    }
}

// Function to check for time overlaps
function check_time_overlaps(frm, current_cdn) {
    // Try different possible field names for the child table
    let work_entries = frm.doc.work_allocation || frm.doc.work || [];
    let overlapping_entries = [];

    console.log('All work entries:', work_entries);
    console.log('Current CDN:', current_cdn);

    // Convert time string to minutes for comparison (handle HH:MM:SS format)
    function time_to_minutes(time_str) {
        if (!time_str) return 0;
        let time_parts = time_str.split(':');
        let hours = parseInt(time_parts[0]);
        let minutes = parseInt(time_parts[1]);
        return hours * 60 + minutes;
    }

    // Check current entry against all others
    let current_row = locals['Work'][current_cdn];
    console.log('Current row from locals:', current_row);

    if (!current_row.expected_start_date || !current_row.end_time) {
        console.log('Missing start or end time for current row');
        return;
    }

    let current_start = time_to_minutes(current_row.expected_start_date);
    let current_end = time_to_minutes(current_row.end_time);

    console.log('Current entry:', {
        title: current_row.work_title,
        start: current_row.expected_start_date,
        end: current_row.end_time,
        start_minutes: current_start,
        end_minutes: current_end
    });

    work_entries.forEach(function(entry, index) {
        console.log('Checking entry:', entry.name, 'vs current:', current_cdn);
        if (entry.name === current_cdn) {
            console.log('Skipping current entry');
            return; // Skip current entry
        }

        if (entry.expected_start_date && entry.end_time) {
            let entry_start = time_to_minutes(entry.expected_start_date);
            let entry_end = time_to_minutes(entry.end_time);

            console.log('Checking against entry:', {
                title: entry.work_title,
                start: entry.expected_start_date,
                end: entry.end_time,
                start_minutes: entry_start,
                end_minutes: entry_end
            });

            // Check for overlap: start1 < end2 && start2 < end1
            let overlap_condition1 = current_start < entry_end;
            let overlap_condition2 = entry_start < current_end;

            console.log('Overlap check:', {
                'current_start < entry_end': overlap_condition1,
                'entry_start < current_end': overlap_condition2,
                'both_true': overlap_condition1 && overlap_condition2
            });

            if (overlap_condition1 && overlap_condition2) {
                console.log('OVERLAP DETECTED!');
                overlapping_entries.push({
                    title: entry.work_title || `Row ${index + 1}`,
                    start: entry.expected_start_date,
                    end: entry.end_time
                });
            }
        } else {
            console.log('Entry missing start or end time:', entry);
        }
    });

    console.log('Overlapping entries found:', overlapping_entries.length);

    // Show warning if overlaps found
    if (overlapping_entries.length > 0) {
        show_overlap_warning(current_row, overlapping_entries);

        // Add visual indicator to the row
        highlight_overlapping_row(frm, current_cdn, true);
    } else {
        // Remove visual indicator if no overlaps
        highlight_overlapping_row(frm, current_cdn, false);
    }
}

// Function to show overlap warning
function show_overlap_warning(current_row, overlapping_entries) {
    let overlap_details = overlapping_entries.map(entry => 
        `• ${entry.title}: ${entry.start} - ${entry.end}`
    ).join('<br>');

    frappe.msgprint({
        title: __('⚠️ Time Overlap Detected'),
        message: `
            <div style="margin-bottom: 15px;">
                <strong>Current Work:</strong> ${current_row.work_title || 'Untitled'}<br>
                <strong>Time:</strong> ${current_row.expected_start_date} - ${current_row.end_time}
            </div>
            <div style="margin-bottom: 15px;">
                <strong>Overlapping with:</strong><br>
                ${overlap_details}
            </div>
            <div style="color: #ff6b6b; font-size: 12px;">
                <em>You can continue, but please review the schedule to avoid conflicts.</em>
            </div>
        `,
        indicator: 'orange'
    });
}

// Function to highlight overlapping rows
function highlight_overlapping_row(frm, cdn, is_overlapping) {
    // Try different possible field names for the child table
    let child_table_field = null;
    if (frm.fields_dict.work_allocation) {
        child_table_field = 'work_allocation';
    } else if (frm.fields_dict.work) {
        child_table_field = 'work';
    }

    if (!child_table_field) {
        console.log('Cannot find child table field for highlighting');
        return;
    }

    let grid_row = frm.fields_dict[child_table_field].grid.grid_rows_by_docname[cdn];

    if (grid_row) {
        let row_element = grid_row.wrapper;

        if (is_overlapping) {
            // Add warning styling
            row_element.style.backgroundColor = '#fff3cd';
            row_element.style.borderLeft = '4px solid #ffc107';

            // Add warning icon if not already present
            if (!row_element.querySelector('.overlap-warning')) {
                let warning_icon = document.createElement('span');
                warning_icon.className = 'overlap-warning';
                warning_icon.innerHTML = '⚠️';
                warning_icon.style.cssText = `
                    position: absolute;
                    right: 10px;
                    top: 10px;
                    font-size: 16px;
                    z-index: 100;
                `;
                warning_icon.title = 'Time overlap detected';
                row_element.style.position = 'relative';
                row_element.appendChild(warning_icon);
            }
        } else {
            // Remove warning styling
            row_element.style.backgroundColor = '';
            row_element.style.borderLeft = '';

            // Remove warning icon
            let warning_icon = row_element.querySelector('.overlap-warning');
            if (warning_icon) {
                warning_icon.remove();
            }
        }
    } else {
        console.log('Grid row not found for highlighting');
    }
}

