// Additional helper function to format time display
function format_time_display(time_str) {
    if (!time_str) return '';
    let [hours, minutes] = time_str.split(':').map(Number);
    let period = hours >= 12 ? 'PM' : 'AM';
    let display_hours = hours % 12 || 12;
    return `${display_hours}:${minutes.toString().padStart(2, '0')} ${period}`;
}

// Function to validate time format
function validate_time_format(time_str) {
    if (!time_str) return false;
    let time_regex = /^([01]?[0-9]|2[0-3]):[0-5][0-9]$/;
    return time_regex.test(time_str);
}

// Client Script for Daily Work Allocation - Project Filter
frappe.ui.form.on('Daily Work Allocation', {
    refresh: function(frm) {
        // Set query for Project field based on Customer, Address, and Job Type
        frm.set_query('custom_project_title', function(doc) {
            let filters = {};
            
            // Add customer filter if customer is selected
            if (doc.custom_customer) {
                filters['customer'] = doc.custom_customer;
            }
            
            // Add address filter if address is selected
            if (doc.custom_address) {
                filters['custom_address'] = doc.custom_address;
            }
            
            // Add job type filter if job type is selected
            if (doc.custom_job_type) {
                filters['custom_job_type'] = doc.custom_job_type;
            }
            
            return {
                filters: filters
            };
        });
    },
    
    // Refresh project filter when customer changes
    custom_customer: function(frm) {
        frm.set_value('custom_project_title', '');
        frm.refresh_field('custom_project_title');
    },
    
    // Refresh project filter when address changes
    custom_address: function(frm) {
        frm.set_value('custom_project_title', '');
        frm.refresh_field('custom_project_title');
    },
    
    // Refresh project filter when job type changes
    custom_job_type: function(frm) {
        frm.set_value('custom_project_title', '');
        frm.refresh_field('custom_project_title');
    }
});

