function validate_work_overlaps(frm, is_save_validation = false, show_toast = false) {
    // Get all work allocations using correct field name
    let allocations = frm.doc.custom_work_allocation || [];
    
    // Filter entries with at least start time
    let valid_allocations = allocations.filter(row => 
        row.expected_start_date && !row.__islocal_deleted
    );
    
    if (valid_allocations.length < 2) {
        // Clear any previous error highlighting
        clear_overlap_highlighting(frm);
        return true;
    }
    
    // Check for overlaps
    let overlaps = [];
    
    for (let i = 0; i < valid_allocations.length; i++) {
        for (let j = i + 1; j < valid_allocations.length; j++) {
            let work1 = valid_allocations[i];
            let work2 = valid_allocations[j];
            
            if (is_overlapping(work1, work2)) {
                overlaps.push({work1, work2});
            }
        }
    }
    
    if (overlaps.length > 0) {
        // Highlight overlapping rows
        highlight_overlapping_rows(frm, overlaps);
        
        if (is_save_validation) {
            // Show error and prevent save
            show_save_error(overlaps);
            return false;
        } else if (show_toast) {
            // Show real-time toast only when explicitly requested
            show_overlap_toast(overlaps);
            return false;
        }
        return false;
    } else {
        // Clear highlighting if no overlaps
        clear_overlap_highlighting(frm);
        return true;
    }
}

function is_overlapping(work1, work2) {
    // Convert to minutes for easy calculation
    let start1 = time_to_minutes(work1.expected_start_date);
    let start2 = time_to_minutes(work2.expected_start_date);
    
    // Default duration to 1 hour if not specified
    let duration1 = work1.expected_time_in_hours ? parseFloat(work1.expected_time_in_hours) : 1;
    let duration2 = work2.expected_time_in_hours ? parseFloat(work2.expected_time_in_hours) : 1;
    
    let end1 = start1 + (duration1 * 60);
    let end2 = start2 + (duration2 * 60);
    
    // Check overlap
    return (start1 < end2 && end1 > start2);
}

function time_to_minutes(time_str) {
    if (!time_str) return 0;
    
    let parts = time_str.split(':');
    if (parts.length === 2) {
        return parseInt(parts[0]) * 60 + parseInt(parts[1]);
    }
    return 0;
}

function minutes_to_time(minutes) {
    let hours = Math.floor(minutes / 60);
    let mins = minutes % 60;
    return `${hours.toString().padStart(2, '0')}:${mins.toString().padStart(2, '0')}`;
}

// Global variable to track shown overlaps to prevent duplicates
let shown_overlaps = new Set();

function show_overlap_toast(overlaps) {
    let first_overlap = overlaps[0];
    let work1 = first_overlap.work1;
    let work2 = first_overlap.work2;
    
    let work1_name = work1.work_title || 'Work Item';
    let work2_name = work2.work_title || 'Work Item';
    
    let start1 = work1.expected_start_date;
    let duration1 = work1.expected_time_in_hours ? parseFloat(work1.expected_time_in_hours) : 1;
    let end1 = minutes_to_time(time_to_minutes(start1) + (duration1 * 60));
    
    let start2 = work2.expected_start_date;
    let duration2 = work2.expected_time_in_hours ? parseFloat(work2.expected_time_in_hours) : 1;
    let end2 = minutes_to_time(time_to_minutes(start2) + (duration2 * 60));
    
    let message = `⚠️ Time Overlap! ${work1_name} (${start1}-${end1}) overlaps with ${work2_name} (${start2}-${end2})`;
    
    if (overlaps.length > 1) {
        message += ` and ${overlaps.length - 1} more conflicts`;
    }
    
    // Create unique key for this overlap
    let overlap_key = `${work1.name}-${work2.name}`;
    
    // Only show if not already shown
    if (!shown_overlaps.has(overlap_key)) {
        frappe.show_alert({
            message: message,
            indicator: 'orange'
        }, 5);
        
        shown_overlaps.add(overlap_key);
        
        // Clear this overlap from shown set after 5 seconds
        setTimeout(() => {
            shown_overlaps.delete(overlap_key);
        }, 5000);
    }
}

function show_save_error(overlaps) {
    let message = '<div style="color: red; font-weight: bold;">⚠️ Cannot Save - Time Overlaps Detected!</div><br>';
    
    overlaps.forEach((overlap, index) => {
        let work1 = overlap.work1;
        let work2 = overlap.work2;
        
        let start1 = work1.expected_start_date;
        let end1 = minutes_to_time(time_to_minutes(start1) + (parseFloat(work1.expected_time_in_hours) * 60));
        
        let start2 = work2.expected_start_date;
        let end2 = minutes_to_time(time_to_minutes(start2) + (parseFloat(work2.expected_time_in_hours) * 60));
        
        message += `<strong>Conflict ${index + 1}:</strong><br>`;
        message += `• ${work1.work_title || 'Work'} (${start1} - ${end1})<br>`;
        message += `• ${work2.work_title || 'Work'} (${start2} - ${end2})<br><br>`;
    });
    
    message += '<div style="color: #666; font-size: 12px;">Please adjust the times to resolve conflicts.</div>';
    
    frappe.throw({
        title: 'Time Overlap Error',
        message: message
    });
}

function highlight_overlapping_rows(frm, overlaps) {
    // Clear previous highlighting
    clear_overlap_highlighting(frm);
    
    // Add CSS for highlighting if not exists
    if (!$('#overlap-highlight-css').length) {
        $('<style id="overlap-highlight-css">')
            .html(`
                .overlap-row {
                    background-color: #ffebee !important;
                    border-left: 4px solid #ff5722 !important;
                    animation: pulse-red 2s infinite;
                }
                .overlap-row .form-control {
                    background-color: #ffebee !important;
                    border-color: #ff5722 !important;
                }
                @keyframes pulse-red {
                    0% { border-left-color: #ff5722; }
                    50% { border-left-color: #ff9800; }
                    100% { border-left-color: #ff5722; }
                }
            `)
            .appendTo('head');
    }
    
    // Highlight overlapping rows using correct field name
    overlaps.forEach(overlap => {
        let alloc1_idx = frm.doc.custom_work_allocation.findIndex(row => row.name === overlap.work1.name);
        let alloc2_idx = frm.doc.custom_work_allocation.findIndex(row => row.name === overlap.work2.name);
        
        if (alloc1_idx !== -1) {
            let row1 = frm.fields_dict.custom_work_allocation.grid.grid_rows[alloc1_idx];
            if (row1) {
                row1.wrapper.addClass('overlap-row');
            }
        }
        
        if (alloc2_idx !== -1) {
            let row2 = frm.fields_dict.custom_work_allocation.grid.grid_rows[alloc2_idx];
            if (row2) {
                row2.wrapper.addClass('overlap-row');
            }
        }
    });
}

function clear_overlap_highlighting(frm) {
    // Remove highlighting from all rows using correct field name
    if (frm.fields_dict.custom_work_allocation && frm.fields_dict.custom_work_allocation.grid) {
        frm.fields_dict.custom_work_allocation.grid.wrapper.find('.overlap-row').removeClass('overlap-row');
    }
}

