function createTaskFromWorkItem(frm, work_item, employee_name, project_title, index) {
    let task_subject = work_item.work_title;
    
    console.log("Checking for existing task with subject:", task_subject);
    
    // Check if task already exists
    frappe.call({
        method: 'frappe.client.get_list',
        args: {
            doctype: 'Task',
            filters: {
                subject: task_subject,
                project: project_title
            },
            fields: ['name', 'subject']
        },
        callback: function(r) {
            console.log("Existing task check result:", r.message);
            
            if (r.message && r.message.length > 0) {
                console.log("Task already exists:", r.message[0].name);
                frappe.show_alert({
                    message: `Task "${task_subject}" already exists`,
                    indicator: 'orange'
                });
                return;
            }
            
            console.log("Creating new task...");
            
            // Calculate proper date for task
            let task_date = frm.doc.date;
            let start_time = work_item.expected_start_date; // This is the correct field name
            
            // Create datetime by combining DWA date with work start time
            let task_start_datetime = null;
            if (start_time && task_date) {
                try {
                    task_start_datetime = frappe.datetime.add_to_date(task_date, {
                        hours: parseInt(start_time.split(':')[0]),
                        minutes: parseInt(start_time.split(':')[1])
                    });
                } catch (e) {
                    console.log("Error parsing time, using date only:", e);
                    task_start_datetime = task_date;
                }
            } else {
                task_start_datetime = task_date;
            }
            
            console.log("Task start datetime:", task_start_datetime);
            
            // Prepare task data
            let task_data = {
                doctype: 'Task',
                subject: work_item.work_title,
                description: work_item.work_description || '',
                project: project_title,
                exp_start_date: task_start_datetime,
                expected_time: work_item.expected_time_in_hours || 0,
                status: 'Open',
                // Add custom field to link back to DWA
                custom_daily_work_allocation: frm.doc.name
            };
            
            console.log("Task data to create:", task_data);
            
            // Create new task
            frappe.call({
                method: 'frappe.client.insert',
                args: {
                    doc: task_data
                },
                callback: function(task_response) {
                    console.log("Task created successfully:", task_response.message);
                    
                    if (task_response.message) {
                        let task_name = task_response.message.name;
                        
                        // Get employee user ID if employee_name is display name
                        getEmployeeUserId(employee_name, function(user_id) {
                            if (user_id) {
                                assignTaskToEmployee(task_name, user_id, work_item.work_title, frm.doc.name);
                            } else {
                                console.log("Could not find user ID for employee:", employee_name);
                                frappe.show_alert({
                                    message: `Task created but could not assign to ${employee_name}`,
                                    indicator: 'orange'
                                });
                            }
                        });
                    }
                },
                error: function(err) {
                    console.log("Task creation error:", err);
                    frappe.show_alert({
                        message: `Task creation failed: ${err.message || err}`,
                        indicator: 'red'
                    });
                }
            });
        },
        error: function(err) {
            console.log("Error checking existing tasks:", err);
            frappe.show_alert({
                message: `Error checking existing tasks: ${err.message || err}`,
                indicator: 'red'
            });
        }
    });
}

function getEmployeeUserId(employee_name, callback) {
    // First try to use employee_name as user ID directly
    frappe.call({
        method: 'frappe.client.get',
        args: {
            doctype: 'User',
            name: employee_name
        },
        callback: function(r) {
            if (r.message) {
                callback(employee_name);
            } else {
                // If not found, search by full name in Employee doctype
                frappe.call({
                    method: 'frappe.client.get_list',
                    args: {
                        doctype: 'Employee',
                        filters: {
                            employee_name: employee_name
                        },
                        fields: ['user_id', 'employee_name']
                    },
                    callback: function(emp_r) {
                        if (emp_r.message && emp_r.message.length > 0) {
                            callback(emp_r.message[0].user_id);
                        } else {
                            callback(null);
                        }
                    }
                });
            }
        }
    });
}

function assignTaskToEmployee(task_name, user_id, task_title, dwa_name) {
    console.log("Assigning task to user:", user_id);
    
    frappe.call({
        method: 'frappe.desk.form.assign_to.add',
        args: {
            assign_to: user_id,
            doctype: 'Task',
            name: task_name,
            description: `Task assigned from Daily Work Allocation: ${dwa_name}`
        },
        callback: function(assign_response) {
            console.log("Task assignment result:", assign_response);
            
            frappe.show_alert({
                message: `Task "${task_title}" created and assigned to ${user_id}`,
                indicator: 'green'
            });
        },
        error: function(err) {
            console.log("Assignment error:", err);
            frappe.show_alert({
                message: `Task created but assignment failed: ${err.message || err}`,
                indicator: 'orange'
            });
        }
    });
}

