// 🏰 Function to fetch employee tasks from the kingdom's records
function fetch_employee_tasks(frm) {
    // Show loading indicator
    frm.set_df_property('work_allocation', 'description', '🔄 Summoning employee tasks...');

    // 🕵️ Search for existing Daily Work Allocation for this employee and date
    frappe.call({
        method: 'frappe.client.get_list',
        args: {
            doctype: 'Daily Work Allocation',
            filters: {
                employee_name: frm.doc.employee_name,
                date: frm.doc.date
            },
            fields: ['name', 'work_allocation'],
            limit: 1
        },
        callback: function(response) {
            if (response.message && response.message.length > 0) {
                // 📜 Found existing allocation, fetch the detailed work allocation
                fetch_existing_work_allocation(frm, response.message[0].name);
            } else {
                // 🆕 No existing allocation, fetch from Task doctype
                fetch_tasks_from_task_doctype(frm);
            }
        }
    });
}

// 📋 Function to fetch existing work allocation details
function fetch_existing_work_allocation(frm, existing_dwa_name) {
    frappe.call({
        method: 'frappe.client.get',
        args: {
            doctype: 'Daily Work Allocation',
            name: existing_dwa_name
        },
        callback: function(response) {
            if (response.message && response.message.work_allocation) {
                // 🎯 Clear existing rows and populate with old data
                frm.clear_table('work_allocation');

                response.message.work_allocation.forEach(function(row) {
                    let new_row = frm.add_child('work_allocation');
                    new_row.project_title = row.project_title;
                    new_row.work_title = row.work_title;
                    new_row.work_description = row.work_description;
                    new_row.start_time = row.start_time;
                    new_row.duration = row.duration;
                });

                frm.refresh_field('work_allocation');
                frm.set_df_property('work_allocation', 'description', '✅ Previous work allocation loaded successfully!');

                // Show success message
                frappe.show_alert({
                    message: '🏰 Previous work allocation has been restored!',
                    indicator: 'green'
                });
            }
        }
    });
}

// 📋 Function to fetch tasks from Task doctype
function fetch_tasks_from_task_doctype(frm) {
    frappe.call({
        method: 'frappe.client.get_list',
        args: {
            doctype: 'Task',
            filters: {
                assigned_to: frm.doc.employee_name,
                status: ['in', ['Open', 'Working', 'Pending Review']],
                exp_start_date: ['<=', frm.doc.date],
                exp_end_date: ['>=', frm.doc.date]
            },
            fields: ['name', 'subject', 'description', 'project', 'expected_time', 'priority'],
            limit: 20
        },
        callback: function(response) {
            if (response.message && response.message.length > 0) {
                populate_work_allocation_table(frm, response.message);
            } else {
                // 🔍 Try alternative filters if no tasks found
                fetch_tasks_alternative_filters(frm);
            }
        }
    });
}

// 🔄 Alternative task fetching with relaxed filters
function fetch_tasks_alternative_filters(frm) {
    frappe.call({
        method: 'frappe.client.get_list',
        args: {
            doctype: 'Task',
            filters: {
                assigned_to: frm.doc.employee_name,
                status: ['in', ['Open', 'Working', 'Pending Review']]
            },
            fields: ['name', 'subject', 'description', 'project', 'expected_time', 'priority'],
            limit: 10
        },
        callback: function(response) {
            if (response.message && response.message.length > 0) {
                populate_work_allocation_table(frm, response.message);
            } else {
                // 🚫 No tasks found
                frm.set_df_property('work_allocation', 'description', '🏜️ No tasks found for this employee');
                frappe.show_alert({
                    message: '🏜️ No active tasks found for this employee',
                    indicator: 'orange'
                });
            }
        }
    });
}

// 🎯 Function to populate work allocation table with tasks
function populate_work_allocation_table(frm, tasks) {
    // Clear existing rows
    frm.clear_table('work_allocation');

    tasks.forEach(function(task) {
        let row = frm.add_child('work_allocation');
        row.project_title = task.project || 'General';
        row.work_title = task.subject;
        row.work_description = task.description || task.subject;
        row.start_time = '09:00:00'; // Default start time
        row.duration = task.expected_time || 1; // Default 1 hour

        // 🎨 Add priority indicator in work title
        if (task.priority === 'High') {
            row.work_title = '🔴 ' + row.work_title;
        } else if (task.priority === 'Medium') {
            row.work_title = '🟡 ' + row.work_title;
        } else if (task.priority === 'Low') {
            row.work_title = '🟢 ' + row.work_title;
        }
    });

    frm.refresh_field('work_allocation');
    frm.set_df_property('work_allocation', 'description', '');

    // Show success message
    frappe.show_alert({
        message: `✨ ${tasks.length} tasks loaded successfully!`,
        indicator: 'green'
    });
}

