frappe.ui.form.on('JobCard-Veneer Pressing', {
    refresh: function(frm) {
        set_address_query_with_title(frm);
    },
    
    custom_party_name: function(frm) {
        // Clear related fields
        frm.set_value('custom_building_name', '');
        frm.set_value('custom_property_no', '');
        frm.set_value('custom_area', '');
        
        // Reset query
        set_address_query_with_title(frm);
    },
    
    custom_building_name: function(frm) {
        if (frm.doc.custom_building_name) {
            // Add error handling for address fetch
            frappe.call({
                method: 'frappe.client.get',
                args: {
                    doctype: 'Address',
                    name: frm.doc.custom_building_name
                },
                callback: function(r) {
                    if (r.message) {
                        // Set Property No from address_line1  
                        frm.set_value('custom_property_no', r.message.address_line1 || '');
                        
                        // Set Area from state
                        frm.set_value('custom_area', r.message.state || '');
                        
                        frm.refresh_fields();
                    } else {
                        frappe.msgprint({
                            title: __('Address Not Found'),
                            indicator: 'red',
                            message: __('The selected address could not be found. Please check if the address exists and is properly linked to the customer.')
                        });
                        
                        // Clear the field
                        frm.set_value('custom_building_name', '');
                    }
                },
                error: function(err) {
                    console.error('Error fetching address:', err);
                    frappe.msgprint({
                        title: __('Error'),
                        indicator: 'red',
                        message: __('Error fetching address details: ') + (err.message || 'Unknown error')
                    });
                    
                    // Clear the field
                    frm.set_value('custom_building_name', '');
                }
            });
        } else {
            frm.set_value('custom_property_no', '');
            frm.set_value('custom_area', '');
        }
    }
});

function set_address_query_with_title(frm) {
    frm.set_query('custom_building_name', function() {
        if (frm.doc.custom_party_name) {
            return {
                query: 'frappe.contacts.doctype.address.address.address_query',
                filters: {
                    link_doctype: 'Customer',
                    link_name: frm.doc.custom_party_name
                }
            };
        } else {
            return {
                filters: [['name', '=', '']]
            };
        }
    });
}

