frappe.ui.form.on('Daily Work Allocation', {
    refresh: function(frm) {
        // Clear old task table when refreshing form
        if (frm.task_table) {
            frm.task_table.remove();
            frm.task_table = null;
        }

        if (frm.doc.employee_name && frm.doc.date) {
            fetch_and_show_tasks(frm);
        }
    },

    employee_name: function(frm) {
        // Remove old task table if any
        if (frm.task_table) {
            frm.task_table.remove();
            frm.task_table = null;
        }

        if (frm.doc.employee_name && frm.doc.date) {
            fetch_and_show_tasks(frm);
        }
    },

    date: function(frm) {
        // Remove old task table if any
        if (frm.task_table) {
            frm.task_table.remove();
            frm.task_table = null;
        }

        if (frm.doc.employee_name && frm.doc.date) {
            fetch_and_show_tasks(frm);
        }
    }
});


function fetch_and_show_tasks(frm) {
    // Step 1: get user_id linked to the employee
    frappe.call({
        method: 'frappe.client.get_value',
        args: {
            doctype: 'Employee',
            filters: { name: frm.doc.employee_name },
            fieldname: ['user_id']
        },
        callback: function(r) {
            if (!r || !r.message || !r.message.user_id) {
                show_message(frm, 'No linked User ID found for this Employee.');
                return;
            }

            let user_id = r.message.user_id;
            let selected_date = frm.doc.date;

            // Step 2: get tasks assigned to or owned by user_id with date filter
            frappe.call({
                method: 'frappe.client.get_list',
                args: {
                    doctype: 'Task',
                    fields: ['name', 'subject', 'status', 'project', 'owner', '_assign', 'exp_start_date', 'creation', 'custom_expected_start_time'],
                    filters: {
                        exp_start_date: selected_date
                    },
                    limit: 100,
                    order_by: 'creation desc'
                },
                callback: function(res) {
                    let tasks = res.message || [];
                    let matching_tasks = [];

                    // Filter tasks where user_id is either owner or in assign list
                    tasks.forEach(task => {
                        let assigned = false;

                        if (task.owner === user_id) {
                            assigned = true;
                        } else if (task._assign) {
                            try {
                                let assigned_users = JSON.parse(task._assign);
                                if (assigned_users.includes(user_id)) {
                                    assigned = true;
                                }
                            } catch (e) {
                                if (task._assign.includes(user_id)) {
                                    assigned = true;
                                }
                            }
                        }

                        if (assigned) matching_tasks.push(task);
                    });

                    // Render task list in form
                    render_task_table(frm, matching_tasks);
                }
            });
        }
    });
}

function render_task_table(frm, tasks) {
    // Remove previous if exists
    if (frm.task_table) {
        frm.task_table.remove();
    }

    let selected_date = frm.doc.date ? frappe.datetime.str_to_user(frm.doc.date) : '';

    let html = `
        <div style="margin: 15px 0; padding: 15px; border: 1px solid #ddd; background: #f9f9f9; border-radius: 5px;">
            <h4>📋 Assigned Tasks for ${frm.doc.employee_name} on ${selected_date}</h4>
    `;

    if (tasks.length) {
        html += `<table style="width:100%; border-collapse: collapse; font-size: 13px;">
            <thead>
                <tr style="background:#eee;">
                    <th style="border: 1px solid #ccc; padding: 8px; text-align:left;">Task Name</th>
                    <th style="border: 1px solid #ccc; padding: 8px; text-align:left;">Status</th>
                    <th style="border: 1px solid #ccc; padding: 8px; text-align:left;">Project</th>
                    <th style="border: 1px solid #ccc; padding: 8px; text-align:left;">Date</th>
                    <th style="border: 1px solid #ccc; padding: 8px; text-align:left;">Start Time</th>
                </tr>
            </thead>
            <tbody>
        `;

        tasks.forEach(task => {
            let task_date = task.exp_start_date ? frappe.datetime.str_to_user(task.exp_start_date) : 'No Date';
            let start_time = task.custom_expected_start_time ? frappe.datetime.str_to_user(task.custom_expected_start_time) : 'No Start Time';
            html += `
                <tr>
                    <td style="border: 1px solid #ccc; padding: 8px;">${task.subject || 'No Subject'}</td>
                    <td style="border: 1px solid #ccc; padding: 8px;">${task.status || 'No Status'}</td>
                    <td style="border: 1px solid #ccc; padding: 8px;">${task.project || 'No Project'}</td>
                    <td style="border: 1px solid #ccc; padding: 8px;">${task_date}</td>
                    <td style="border: 1px solid #ccc; padding: 8px;">${task.custom_expected_start_time}</td>
                </tr>
            `;
        });

        html += `</tbody></table>
                <p style="margin-top: 10px; font-size: 12px; color: gray;">Total: ${tasks.length} task(s) for ${selected_date}</p>`;
    } else {
        html += `
            <p>No tasks assigned to this employee for ${selected_date}.</p>
        `;
    }

    html += `</div>`;

    frm.task_table = $(html);
    frm.$wrapper.find('.form-layout').append(frm.task_table);
}

function show_message(frm, msg) {
    if (frm.task_table) {
        frm.task_table.remove();
    }

    let html = `
        <div style="margin: 20px 0; padding: 15px; border: 1px solid #f5c6cb; background: #f8d7da; color:#721c24; border-radius: 5px;">
            ${msg}
        </div>
    `;

    frm.task_table = $(html);
    frm.$wrapper.find('.form-layout').append(frm.task_table);
}

frappe.ui.form.on('Payment', {
    refresh: function(frm) {
        setup_attachment_preview(frm);

        // Listen for file uploads after input is ready
        setTimeout(function() {
            if (frm.fields_dict.attachments && frm.fields_dict.attachments.$input) {
                frm.fields_dict.attachments.$input.on('change', function() {
                    setTimeout(function() {
                        setup_attachment_preview(frm);
                    }, 700);
                });
            }
        }, 500);
    },

    after_save: function(frm) {
        setup_attachment_preview(frm);
    },

    attachments: function(frm) {
        setup_attachment_preview(frm);
    }
});

function setup_attachment_preview(frm) {
    // Defensive: Check if the HTML field exists
    if (!frm.fields_dict.attachment_preview) return;

    frm.fields_dict.attachment_preview.$wrapper.empty();

    const file_url = frm.doc.attachments;

